<template><ElConfigProvider namespace="kel"><div class="native-flow-context">
 <div v-if="kind==='overview'" class="flow-overview"><section><div class="section-title"><h3>Flow 定义</h3><KsButton size="small" @click="emit('tab','Builder')">打开编辑器 →</KsButton></div><p class="description">{{description||'尚无说明'}}</p><dl class="kv"><dt>Namespace</dt><dd>{{flow?.namespace||'—'}}</dd><dt>Flow ID</dt><dd><code>{{flow?.flow_id||'—'}}</code></dd><dt>版本</dt><dd>Revision {{flow?.revision||'—'}}</dd><dt>目标类型</dt><dd>{{flow?.target_type||'—'}}</dd><dt>触发方式</dt><dd>{{triggers.length?triggers.map(t=>t.cron||t.type.split('.').at(-1)).join(' · '):controlled?'项目范围调度 / 手动':'手动'}}</dd><dt>项目</dt><dd>{{flow?.project_id}}</dd></dl><div class="section-title recent-title"><h3>最近执行</h3><button class="text-link" @click="emit('tab','Executions')">查看全部 →</button></div><button v-for="run in executions.slice(0,5)" :key="run.id" class="recent-run" @click="emit('navigate','/flows/executions/'+run.id)"><KsExecutionStatus v-if="run.engine?.state?.current" :status="run.engine.state.current" size="small"/><code>{{run.id.slice(0,12)}}</code><span>{{run.targets?.length||0}} targets</span><span>{{elapsed(run)}}</span><span>revision {{run.flow_revision}}</span></button><p v-if="!executions.length" class="empty">尚无执行记录</p></section><aside class="outline"><h3>任务结构</h3><button v-for="(task,index) in taskOutline" :key="task.id" @click="emit('task',task.id)"><span>{{index+1}}</span><div><b>{{task.title}}</b><small>{{task.type}}</small></div><ChevronRight :size="15"/></button><p v-if="!taskOutline.length" class="empty">尚无任务；进入编辑器添加。</p></aside></div>
 <div v-else-if="kind==='revisions'" class="revisions"><aside><h3>版本历史</h3><button v-for="row in orderedRevisions" :key="row.revision" :class="{active:selected?.revision===row.revision}" @click="revision=Number(row.revision)"><b>Revision {{row.revision}}</b><span v-if="row.revision===flow?.revision">当前版本</span><small>{{row.updated||row.updatedAt||row.createdAt?date(row.updated||row.updatedAt||row.createdAt):'修改时间未返回'}}</small></button><p v-if="!orderedRevisions.length" class="empty">尚无可用版本</p></aside><section><div class="section-title"><h3>Revision {{selected?.revision||'—'}} → 当前草稿</h3><KsButton size="small" :disabled="!canEdit||!selected?.source" @click="emit('restore',selected.source)">恢复为新草稿</KsButton></div><div class="diff-head"><span>历史修订</span><span>当前草稿</span></div><NativeDiffEditor v-if="selected?.source!==undefined" :original="selected.source" :modified="source"/><p v-else class="empty">选择含源定义的历史修订；缺失源定义时不能生成差异。</p></section></div>
 <section v-else-if="kind==='triggers'" class="triggers"><div class="section-title"><h3>触发器</h3><KsButton :disabled="!canEdit" @click="addOpen=true">＋ 添加 Schedule</KsButton></div><div v-for="(trigger,index) in triggers" :key="trigger.id" class="trigger-row"><ClockOutline :size="23"/><div><b>{{trigger.id}}</b><small>{{trigger.cron||trigger.type}} · {{trigger.timezone||'未指定时区'}}</small></div><span class="type-tag">{{trigger.type.split('.').at(-1)}}</span><span class="grow"/><span :class="['trigger-state',{enabled:!trigger.disabled}]"><i/>{{trigger.disabled?'已停用':'已启用'}}</span><KsButton size="small" :disabled="!canEdit" @click="emit('toggle',index)">{{trigger.disabled?'启用草稿':'停用草稿'}}</KsButton></div><p v-if="!triggers.length" class="empty">当前 Flow 尚无触发器</p><small class="note">修改保留在同一 Flow 草稿中，校验保存后生效。</small><KsDialog v-model="addOpen" :teleported="false" :appendToBody="false" title="添加 Schedule" width="500px"><div class="trigger-form"><label>Trigger ID<KsInput v-model="newId"/></label><label>Cron<KsInput v-model="cron" placeholder="0 */6 * * *"/></label><label>Timezone<KsInput v-model="zone"/></label><small v-if="triggers.some(t=>t.id===newId)">Trigger ID 已存在</small></div><template #footer><KsButton @click="addOpen=false">取消</KsButton><KsButton type="primary" :disabled="!canEdit||!newId||!cron||triggers.some(t=>t.id===newId)" @click="emit('addTrigger',{id:newId,cron,timezone:zone});addOpen=false">添加到草稿</KsButton></template></KsDialog></section>
 </div></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import YAML from 'yaml';import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';import KsExecutionStatus from '../../vendor/kestra/design-system/components/Data/KsExecutionStatus/KsExecutionStatus.vue';import ChevronRight from 'vue-material-design-icons/ChevronRight.vue';import ClockOutline from 'vue-material-design-icons/ClockOutline.vue';import NativeDiffEditor from './NativeDiffEditor.vue';import {isControlled,inputDefault} from '../flows/definition';
const props=defineProps<{kind:string;flow?:any;description?:string;source:string;executions:any[];revisions:any[];canEdit:boolean}>(),emit=defineEmits(['tab','task','navigate','restore','toggle','addTrigger']);const revision=ref<number|null>(null),addOpen=ref(false),newId=ref('schedule'),cron=ref(''),zone=ref('UTC');
const doc=computed(()=>{try{return YAML.parse(props.source)||{}}catch{return {}}}),controlled=computed(()=>isControlled(doc.value)),triggers=computed<any[]>(()=>doc.value.triggers||[]),orderedRevisions=computed(()=>[...props.revisions].sort((a,b)=>b.revision-a.revision)),selected=computed(()=>orderedRevisions.value.find(r=>r.revision===revision.value)||orderedRevisions.value[0]);
const taskOutline=computed(()=>controlled.value?inputDefault(doc.value,'steps',[]).map((s:any)=>({id:'step:'+s.id,title:s.id,type:s.kind==='python'?'Python Script':s.kind==='bash'?'Shell Script':'Command'})):(doc.value.tasks||[]).map((t:any)=>({id:t.id,title:t.description||t.id,type:t.type?.split('.').at(-1)||'未知类型'})));
const date=(v:string)=>Number.isFinite(Date.parse(v))?new Date(v).toLocaleString():'未返回';function elapsed(run:any){const a=Date.parse(run.engine?.state?.startDate),b=Date.parse(run.engine?.state?.endDate);return Number.isFinite(a)&&Number.isFinite(b)?Math.max(0,(b-a)/1000).toFixed(1)+'s':'未结束 / 未采集'}
</script>
<style scoped>.native-flow-context{color:var(--ks-text-primary);font:12px/1.5 var(--ks-font-family-sans)}.section-title{display:flex;align-items:center;justify-content:space-between;gap:15px;min-height:45px}.section-title h3,.outline>h3,.revisions h3{font-size:14px;font-weight:600;margin:0}.flow-overview{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:24px;padding:8px 0}.flow-overview>section{padding:10px 20px 20px;border:1px solid var(--ks-border-default);border-radius:6px;background:var(--ks-bg-surface)}.description{font-size:12px;color:var(--ks-text-secondary);margin:10px 0 20px}.kv{display:grid;grid-template-columns:120px 1fr;gap:15px;margin:20px 0}.kv dt{font-size:11px;color:var(--ks-text-secondary)}.kv dd{font-size:12px;margin:0;overflow-wrap:anywhere}.outline{border:1px solid var(--ks-border-default);border-radius:6px;background:var(--ks-bg-surface);padding:18px}.outline>h3{margin-bottom:16px}.outline>button{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--ks-border-default);width:100%;text-align:left}.outline>button>span{font-size:10px;color:var(--ks-text-secondary)}.outline>button>div{flex:1;min-width:0}.outline b{font-size:12px}.outline small{display:block;font-size:10px;color:var(--ks-text-secondary);margin-top:5px}.recent-title{margin-top:28px}.text-link{font-size:11px;color:var(--ks-text-link)}.recent-run{display:flex;align-items:center;gap:16px;width:100%;padding:15px 0;border-top:1px solid var(--ks-border-default);text-align:left}.recent-run code{font-size:10px}.recent-run>span{font-size:10px;color:var(--ks-text-secondary)}.empty{padding:35px 15px;color:var(--ks-text-secondary);font-size:11px}.revisions{display:grid;grid-template-columns:215px minmax(0,1fr);min-height:540px;border:1px solid var(--ks-border-default);border-radius:6px;overflow:hidden;background:var(--ks-bg-surface)}.revisions>aside{border-right:1px solid var(--ks-border-default);padding:18px 12px;background:var(--ks-bg-base)}.revisions aside>h3{padding:0 8px 14px}.revisions aside>button{display:block;width:100%;padding:14px 10px;text-align:left;border:1px solid transparent;border-radius:5px;margin:5px 0}.revisions aside>button.active{border-color:var(--ks-border-default);background:var(--ks-bg-tag)}.revisions aside b{font-size:12px}.revisions aside span,.revisions aside small{display:block;font-size:10px;color:var(--ks-text-secondary);margin-top:5px}.revisions>section{min-width:0}.revisions .section-title{padding:14px 18px}.diff-head{display:grid;grid-template-columns:1fr 1fr;padding:8px 20px;border-block:1px solid var(--ks-border-default);font-size:10px;color:var(--ks-text-secondary)}.triggers{border:1px solid var(--ks-border-default);border-radius:6px;padding:12px 20px 22px;background:var(--ks-bg-surface)}.trigger-row{display:flex;align-items:center;gap:15px;border-top:1px solid var(--ks-border-default);padding:20px 0}.trigger-row b{font-size:12px}.trigger-row small{display:block;font-size:10px;color:var(--ks-text-secondary);margin-top:5px}.type-tag{font-size:10px;border:1px solid var(--ks-border-default);border-radius:4px;padding:3px 7px}.grow{flex:1}.trigger-state{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--ks-text-secondary)}.trigger-state.enabled{color:var(--ks-text-success)}.trigger-state i{height:5px;width:5px;background:currentColor;border-radius:50%}.note{display:block;color:var(--ks-text-secondary);font-size:10px;margin-top:15px}.trigger-form{display:grid;gap:15px}.trigger-form label{font-size:12px}.trigger-form :deep(.kel-input){margin-top:8px}@media(max-width:1050px){.flow-overview{grid-template-columns:minmax(0,1fr) 250px}.recent-run{gap:8px}}</style>
